#!/usr/bin/env bash\n\nset -euo pipefail\n\nif [[ $# -ne 2 ]]; then\n  echo "Usage: $0 <old.env> <new.env>"\n  exit 1\nfi\n\nold_file=$1\nnew_file=$2\n\ndeclare -A old new\n\n# Load old env\nwhile IFS='=' read -r key value; do\n  # Skip comments and empty lines\n  [[ -z "$key" ]] && continue\n  [[ "$key" =~ ^# ]] && continue\n  old["$key"]="$value"\n done < <(grep -v '^#' "$old_file" | grep -v '^$' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')\n\n# Load new env\nwhile IFS='=' read -r key value; do\n  [[ -z "$key" ]] && continue\n  [[ "$key" =~ ^# ]] && continue\n  new["$key"]="$value"\n done < <(grep -v '^#' "$new_file" | grep -v '^$' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')\n\n# Detect removed variables\nfor k in "${!old[@]}"; do\n  if [[ -z "${new[$k]+x}" ]]; then\n    echo "Removed: $k"\n  fi\n done\n\n# Detect added variables\nfor k in "${!new[@]}"; do\n  if [[ -z "${old[$k]+x}" ]]; then\n    echo "Added: $k"\n  fi\n done\n\n# Detect changed variables\nfor k in "${!old[@]}"; do\n  if [[ -n "${new[$k]+x}" && "${old[$k]}" != "${new[$k]}" ]]; then\n    echo "Changed: $k (\"${old[$k]}\" -> \"${new[$k]}\")"\n  fi\n done\n
